new_mr = [
    {"id":"madecassoside","names":["Madecassoside","Centella Asiatica Triterpene Glycoside","Cica Active"],"risk":"green","category":"Skin Conditioner","purpose":"The most potent isolated active from Centella Asiatica — stimulates collagen synthesis and dramatically reduces redness.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Madecassoside is a triterpene glycoside isolated from Centella asiatica, and the most pharmacologically active compound in cica. Clinical studies at 0.1-1% concentrations show significant wound healing acceleration, collagen I and III stimulation, and anti-inflammatory effects. Superior to using whole Centella extract.","description_th":"แมดิแคสโซไซด์เป็นไตรเทอร์พีนไกลโคไซด์ที่แยกได้จาก Centella asiatica และเป็นสารที่มีฤทธิ์ทางเภสัชวิทยาสูงสุดในซิกา การศึกษาทางคลินิกแสดงการรักษาแผลที่เร็วขึ้นอย่างมีนัยสำคัญ กระตุ้นคอลลาเจน I และ III"},
    {"id":"magnesium-ascorbyl-phosphate","names":["Magnesium Ascorbyl Phosphate","MAP","Vitamin C MAP"],"risk":"green","category":"Antioxidant","purpose":"Highly stable water-soluble Vitamin C derivative that brightens skin with minimal irritation.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Magnesium Ascorbyl Phosphate (MAP) is a stable, water-soluble Vitamin C ester that is enzymatically converted to L-ascorbic acid in skin. Effective at 5-10%, it inhibits tyrosinase, stimulates collagen, and has antioxidant properties with significantly less irritation than pure Vitamin C.","description_th":"แมกนีเซียม แอสคอร์บิล ฟอสเฟต (MAP) เป็นอนุพันธ์วิตามินซีที่เสถียรและละลายน้ำได้ แปลงเป็น L-แอสคอร์บิก แอซิดโดยเอนไซม์ในผิว มีประสิทธิภาพ 5-10% ยับยั้งไทโรซิเนส กระตุ้นคอลลาเจน"},
    {"id":"magnesium-aluminum-silicate","names":["Magnesium Aluminum Silicate","MAS","Veegum","Smectite Clay"],"risk":"green","category":"Thickener","purpose":"Natural clay mineral used as a rheology modifier and stabilizer in gels and emulsions.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Magnesium Aluminum Silicate is a naturally occurring smectite clay mineral. It functions as a thickener, stabilizer, and suspending agent. Creates elegant textures and improves product stability across temperature extremes. Non-comedogenic and very well-tolerated.","description_th":"แมกนีเซียม อะลูมินัม ซิลิเกตเป็นแร่ดินเหนียวสเมกไทต์ที่เกิดขึ้นตามธรรมชาติ ทำหน้าที่เป็นสารทำให้ข้น สารทำให้เสถียร และสารแขวนลอย สร้างเนื้อสัมผัสที่สวยงาม"},
    {"id":"magnesium-stearate","names":["Magnesium Stearate","Magnesium Salt of Stearic Acid"],"risk":"green","category":"Lubricant","purpose":"Slip agent and lubricant widely used in pressed powder makeup and as a flow agent in cosmetics.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Magnesium Stearate is the magnesium salt of stearic acid. Used as a lubricant, anti-caking agent, and slip agent in pressed powders, eye shadows, blushes, and tablets. Provides a smooth, silky texture to powder products. Very safe and widely approved.","description_th":"แมกนีเซียม สเตียเรตเป็นเกลือแมกนีเซียมของกรดสเตียริก ใช้เป็นสารหล่อลื่น สารต้านการจับตัว และสารให้ความลื่นในแป้งอัด อายแชโดว์ และบลัชออน"},
    {"id":"mandarin-extract","names":["Mandarin Extract","Citrus Reticulata Peel Extract","Mandarin Orange Extract"],"risk":"yellow","category":"Antioxidant","purpose":"Antioxidant citrus extract rich in polymethoxylated flavones with anti-aging and brightening properties.","concerns":["Contains limonene — fragrance allergen","Phototoxic if peel oil included"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Mandarin Extract from Citrus reticulata peel is rich in polymethoxylated flavones (PMFs) like tangeretin and nobiletin — unique citrus flavonoids with anti-inflammatory and anti-aging properties not found in other citrus fruits. Use peel-oil-free extracts to avoid phototoxicity.","description_th":"สารสกัดส้มแมนดาริน อุดมด้วยโพลีเมทอกซีเลเต็ด ฟลาโวนส์ (PMFs) เช่น แทงเจอรีตินและโนบิเลตินซึ่งเป็นฟลาโวนอยด์ส้มเฉพาะที่มีคุณสมบัติต้านการอักเสบและต้านวัย"},
    {"id":"mastic-resin","names":["Mastic Resin Extract","Pistacia Lentiscus Resin","Chios Mastic"],"risk":"green","category":"Antioxidant","purpose":"Ancient Greek resin with potent antioxidant, antibacterial, and anti-biofilm properties.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Mastic Resin from the Pistacia lentiscus tree of Chios, Greece, contains triterpene acids (masticadienonic, oleanolic acids) and polymeric compounds. Has exceptional antibacterial activity against oral bacteria, antioxidant effects, and anti-biofilm properties. Used in oral care and skincare.","description_th":"เรซินแมสติกจากต้น Pistacia lentiscus ในเกาะคิออส กรีซ มีกรดไตรเทอร์พีนและสารประกอบโพลีเมอร์ มีฤทธิ์ต้านเชื้อแบคทีเรียในช่องปากและต้านอนุมูลอิสระที่ยอดเยี่ยม"},
    {"id":"microcrystalline-cellulose","names":["Microcrystalline Cellulose","MCC","Avicel"],"risk":"green","category":"Thickener","purpose":"Refined cellulose used as a thickener, binder, and bulking agent in emulsions and powder cosmetics.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Microcrystalline Cellulose is a refined form of cellulose produced by acid hydrolysis of plant-derived cellulose. Used as a thickener, binder, stabilizer, and anti-caking agent. Forms gel-like dispersions and improves the stability of emulsions and suspensions.","description_th":"ไมโครคริสตัลลีน เซลลูโลสเป็นเซลลูโลสที่ผ่านการกลั่นบริสุทธิ์ผลิตโดยการไฮโดรไลซิสด้วยกรดจากเซลลูโลสจากพืช ใช้เป็นสารทำให้ข้น สารยึดเกาะ สารทำให้เสถียร"},
    {"id":"niacinamide","names":["Niacinamide","Vitamin B3","Nicotinamide"],"risk":"green","category":"Skin Conditioner","purpose":"Multi-functional vitamin B3 derivative addressing pores, redness, hyperpigmentation, and skin aging.","concerns":["Flushing reaction possible at very high concentrations (>4%+)","May cause slight warmth on application initially"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Niacinamide (Vitamin B3) is one of the most studied and versatile cosmetic actives. At 2-10%, it reduces pore appearance, evens skin tone, reduces hyperpigmentation (by inhibiting melanosome transfer), improves barrier function, and has anti-inflammatory effects. Compatible with most other actives.","description_th":"ไนอาซินาไมด์ (วิตามิน B3) เป็นหนึ่งในสารออกฤทธิ์เครื่องสำอางที่มีการศึกษามากที่สุดและหลากหลายที่สุด ที่ 2-10% ลดรูขุมขน ทำให้สีผิวสม่ำเสมอ ลดรอยดำ (โดยการยับยั้งการถ่ายโอนเมลาโนโซม) ปรับปรุงการทำงานของเกราะป้องกัน"},
    {"id":"neroli-oil","names":["Neroli Oil","Citrus Aurantium Flower Oil","Orange Blossom Oil","Citrus Bigaradia Flower Oil"],"risk":"yellow","category":"Fragrance","purpose":"Luxury citrus blossom oil with a distinctive floral scent, skin regenerating and calming properties.","concerns":["Multiple EU-listed fragrance allergens (linalool, geraniol, farnesol, benzyl benzoate)","Potential sensitizer","Use at low concentrations"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Neroli Oil is steam-distilled from the blossoms of Citrus aurantium bigaradia. One of the most prized and expensive essential oils, it contains linalool, linalyl acetate, and geraniol. Has skin-regenerating, mood-enhancing properties and a distinctive, complex citrus-floral scent.","description_th":"น้ำมันเนโรลีกลั่นด้วยไอน้ำจากดอก Citrus aurantium เป็นหนึ่งในน้ำมันหอมระเหยที่ล้ำค่าและแพงที่สุด มีลินาลูล ลินาลิล อะซิเตท และจีรานิออล มีคุณสมบัติฟื้นฟูผิว"},
    {"id":"oligomeric-proanthocyanidins","names":["Oligomeric Proanthocyanidins","OPC","Pycnogenol","Pine Bark Extract","Grape Seed Proanthocyanidins"],"risk":"green","category":"Antioxidant","purpose":"The most potent class of plant-derived antioxidants with 20× greater ORAC value than Vitamin E.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Oligomeric Proanthocyanidins (OPC/Pycnogenol) are flavanoid polymers from pine bark or grape seeds with 20× greater antioxidant capacity than Vitamin E and 50× greater than Vitamin C. They bind collagen, protect capillaries, and inhibit UV-induced MMP enzymes, providing exceptional anti-aging benefits.","description_th":"โปรแอนโทไซยานิดิน (OPC/ไพก์โนจีนอล) เป็นโพลิเมอร์ฟลาแวนอยด์จากเปลือกสนหรือเมล็ดองุ่น มีความสามารถต้านอนุมูลอิสระมากกว่าวิตามินอี 20 เท่า จับคอลลาเจน ปกป้องหลอดเลือดฝอย"},
    {"id":"papaya-extract","names":["Papaya Extract","Carica Papaya Fruit Extract","Papain Extract"],"risk":"green","category":"Exfoliant","purpose":"Enzyme papain from papaya provides gentle enzymatic exfoliation and skin brightening.","concerns":["Potential allergen in latex-sensitive individuals (cross-reactivity)","High concentrations may irritate"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Papaya Extract from Carica papaya contains papain (a cysteine protease) and chymopapain. Papain gently breaks down dead skin protein for enzymatic exfoliation. Also contains Vitamin C, beta-carotene, and flavonoids with antioxidant and brightening properties.","description_th":"สารสกัดมะละกอมีปาเปน (ซิสเตอีนโปรตีเอส) และไคโมปาเปน ปาเปนสลายโปรตีนผิวที่ตายแล้วอย่างอ่อนโยนเพื่อการผลัดเซลล์ผิวด้วยเอนไซม์ มีวิตามินซี เบตา-แคโรทีน และฟลาโวนอยด์"},
    {"id":"pantethine","names":["Pantethine","Bis-Pantothenyl Sulfide","D-Pantethine"],"risk":"green","category":"Skin Conditioner","purpose":"Advanced form of Vitamin B5 with superior skin barrier restoration and anti-inflammatory properties.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Pantethine is the active coenzyme form of Vitamin B5, superior to panthenol as it bypasses one metabolic conversion step. Studies show excellent skin barrier restoration, reduction of TEWL, anti-inflammatory, and wound-healing properties. Used in sensitive and post-procedure skin care.","description_th":"แพนเทธีนเป็นรูปแบบโคเอนไซม์ออกฤทธิ์ของวิตามิน B5 ดีกว่าแพนเทนอลเพราะข้ามขั้นตอนการแปลงสารเมแทบอลิซึมหนึ่งขั้นตอน การศึกษาแสดงการฟื้นฟูเกราะป้องกันผิวที่ยอดเยี่ยม"},
    {"id":"pearl-extract","names":["Pearl Extract","Pearl Powder","Hydrolyzed Pearl","Conchiolin"],"risk":"green","category":"Skin Brightener","purpose":"Traditional luxury beauty ingredient rich in amino acids and conchiolin protein with brightening properties.","concerns":["Not vegan","Expensive — often present at ineffective concentrations"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Pearl Extract contains conchiolin (a structural protein), calcium carbonate, amino acids, and trace minerals. Historically used in Asian skincare for thousands of years for brightening and smoothing. Hydrolyzed Pearl Powder absorbs better than raw pearl powder and conditions skin.","description_th":"สารสกัดไข่มุกมีคอนไคโอลิน (โปรตีนโครงสร้าง) แคลเซียมคาร์บอเนต กรดอะมิโน และแร่ธาตุร่องรอย ใช้ในสกินแคร์เอเชียมาหลายพันปีเพื่อทำให้ผิวสว่างและเนียน"},
    {"id":"peony-extract","names":["Peony Extract","Paeonia Lactiflora Root Extract","White Peony Extract"],"risk":"green","category":"Skin Brightener","purpose":"Traditional East Asian beauty botanical with whitening, anti-inflammatory, and anti-aging properties.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"White Peony (Paeonia lactiflora) Root Extract contains paeoniflorin, paeonol, and gallic acid. Paeoniflorin inhibits tyrosinase and melanosome transfer, making it an effective brightening agent. Also has anti-inflammatory and antioxidant properties. Traditional in Japanese and Korean skincare.","description_th":"สารสกัดรากโบตั๋นขาว (Paeonia lactiflora) มีเพโอนิฟลอริน เพโอนอล และกรดแกลลิก เพโอนิฟลอรินยับยั้งไทโรซิเนสและการถ่ายโอนเมลาโนโซม เป็นสารทำให้ผิวสว่างที่มีประสิทธิภาพ"},
    {"id":"pine-bark-extract","names":["Pine Bark Extract","Pinus Pinaster Extract","Pycnogenol Source","Maritime Pine Extract"],"risk":"green","category":"Antioxidant","purpose":"Standardized OPC extract from maritime pine bark with exceptional antioxidant and anti-aging properties.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Maritime Pine Bark Extract (Pycnogenol source) contains oligomeric proanthocyanidins (OPC), taxifolin, catechin, and phenolic acids. One of the most clinically studied botanical antioxidants — shown to improve skin hydration, elasticity, and reduce UV-induced damage.","description_th":"สารสกัดเปลือกสนทะเล (แหล่ง Pycnogenol) มีโปรแอนโทไซยานิดิน (OPC) แทกซิโฟลิน คาเทชิน และกรดฟีนอลิก เป็นสารต้านอนุมูลอิสระจากพฤกษาที่มีการศึกษาทางคลินิกมากที่สุด"},
    {"id":"phytol","names":["Phytol","Diterpene Alcohol","Plant Chlorophyll Residue"],"risk":"green","category":"Skin Conditioner","purpose":"Natural plant alcohol from chlorophyll degradation with antioxidant and skin conditioning properties.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Phytol is a natural acyclic diterpene alcohol derived from the degradation of chlorophyll. Found naturally in green plants and spirulina. In cosmetics, it acts as an antioxidant, skin conditioner, and fragrance ingredient with a mild floral-herbal scent.","description_th":"ไฟทอลเป็นแอลกอฮอล์ไดเทอร์พีนอะไซคลิกธรรมชาติที่ได้จากการย่อยสลายคลอโรฟิลล์ พบตามธรรมชาติในพืชสีเขียวและสไปรูลีนา ในเครื่องสำอางทำหน้าที่เป็นสารต้านอนุมูลอิสระและปรับสภาพผิว"},
    {"id":"plant-stem-cells","names":["Plant Stem Cells","Malus Domestica Stem Cell","Rosa Damascena Stem Cell","Vitis Vinifera Stem Cell"],"risk":"green","category":"Anti-aging","purpose":"Biotechnology-derived plant stem cell extracts that protect human skin stem cells from aging damage.","concerns":["Efficacy claims often outpace clinical evidence","The plant stem cells themselves do not become human stem cells"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Plant Stem Cell technology involves culturing plant callus cells and using their filtrate as cosmetic actives. These extracts contain epigenetic regulators, metabolites, and growth factors that can protect skin's own stem cell populations from UV and oxidative damage.","description_th":"เทคโนโลยีเซลล์ต้นกำเนิดพืชเกี่ยวข้องกับการเพาะเลี้ยงเซลล์แคลลัสพืชและใช้น้ำกรองเป็นสารออกฤทธิ์เครื่องสำอาง สารสกัดเหล่านี้มีสารควบคุมเอพิจีเนติก เมแทบอไลต์ และปัจจัยเจริญเติบโต"},
    {"id":"polyglutamic-acid","names":["Polyglutamic Acid","PGA","Natto-derived PGA"],"risk":"green","category":"Humectant","purpose":"4× more hydrating than hyaluronic acid — fermented soybean-derived humectant that also inhibits hyaluronidase.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Polyglutamic Acid (PGA) is produced by Bacillus subtilis fermentation of soybeans (natto). It holds 4× more water than hyaluronic acid per unit weight and additionally inhibits hyaluronidase (the enzyme that breaks down HA), extending the skin's own HA levels.","description_th":"กรดโพลีกลูตามิก (PGA) ผลิตโดยการหมักถั่วเหลือง (นัตโตะ) ด้วย Bacillus subtilis กักเก็บน้ำได้มากกว่ากรดไฮยาลูโรนิก 4 เท่าต่อหน่วยน้ำหนัก และยังยับยั้ง hyaluronidase เอนไซม์ที่สลาย HA"},
    {"id":"propolis-wax","names":["Propolis Wax","Bee Propolis Wax","Cera Alba-like Propolis"],"risk":"yellow","category":"Antimicrobial","purpose":"Solid wax fraction of propolis with film-forming, antimicrobial, and wound-healing properties.","concerns":["Potential allergen — bee products","Not vegan"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Propolis Wax is the solid, non-resinous fraction of propolis with film-forming properties. Used in lip care, stick cosmetics, and wound-healing formulas. Provides antimicrobial protection and a protective film. Contains flavonoids and phenolics at lower concentrations than propolis resin.","description_th":"โพรโพลิสแว็กซ์เป็นส่วนที่เป็นของแข็งและไม่เป็นเรซินของโพรโพลิส มีคุณสมบัติสร้างฟิล์ม ใช้ในผลิตภัณฑ์ดูแลริมฝีปากและสูตรรักษาแผล"},
    {"id":"retinal","names":["Retinal","Retinaldehyde","Vitamin A Aldehyde"],"risk":"yellow","category":"Anti-aging","purpose":"The most potent retinoid available without a prescription — converts to retinoic acid 11× faster than retinol.","concerns":["More irritating than retinol","Start at low concentrations","Avoid during pregnancy","Increase sun sensitivity — use SPF","Do not use with AHAs/BHAs simultaneously"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Retinal (Retinaldehyde) is just one enzymatic step away from retinoic acid (the active form), compared to retinol's two steps. This makes it approximately 11 times more potent than retinol with faster results. Clinical studies show superior wrinkle reduction and skin renewal compared to retinol.","description_th":"เรตินัล (เรตินัลดีไฮด์) อยู่ห่างจากกรดเรตินอิก (รูปแบบออกฤทธิ์) เพียงหนึ่งขั้นตอนเอนไซม์ ทำให้มีประสิทธิภาพมากกว่าเรตินอลประมาณ 11 เท่าพร้อมผลที่เร็วกว่า"},
    {"id":"retinyl-retinoate","names":["Retinyl Retinoate","Retinoate Ester","Super Retinol"],"risk":"yellow","category":"Anti-aging","purpose":"Dual-action retinoid ester that is effective and significantly less irritating than retinol or retinaldehyde.","concerns":["Avoid during pregnancy","Increases sun sensitivity","Not for very sensitive skin at high concentrations"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Retinyl Retinoate is a unique retinoid ester combining retinol and retinoic acid in one molecule. Hydrolyzed in skin to release both retinol and retinoic acid simultaneously. Clinical studies show comparable efficacy to tretinoin with significantly less irritation, making it suitable for sensitive skin.","description_th":"เรตินิล เรตินโอเอตเป็นเอสเตอร์เรตินอยด์เฉพาะที่รวมเรตินอลและกรดเรตินอิกไว้ในโมเลกุลเดียว ไฮโดรไลซ์ในผิวเพื่อปล่อยเรตินอลและกรดเรตินอิกพร้อมกัน ประสิทธิภาพใกล้เคียงกับเตรทินอินแต่ระคายเคืองน้อยกว่า"},
    {"id":"sodium-dna","names":["Sodium DNA","Sodium Deoxyribonucleate","DNA (from salmon/plant)"],"risk":"green","category":"Skin Conditioner","purpose":"DNA fragments that provide deep hydration and cell-signaling support for skin repair and anti-aging.","concerns":["Animal-derived source (salmon) vs plant-derived — check for vegan variants"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Sodium DNA consists of sodium salt of DNA fragments derived from salmon milt or plant sources. Provides intense hydration, stimulates fibroblast activity, and may support DNA repair signaling in skin cells. Used in premium anti-aging serums and hydrating treatments.","description_th":"โซเดียม DNA ประกอบด้วยเกลือโซเดียมของชิ้นส่วน DNA จากน้ำนมปลาแซลมอนหรือแหล่งพืช ให้ความชุ่มชื้นอย่างเข้มข้น กระตุ้นกิจกรรมไฟโบรบลาสต์ ใช้ในเซรั่มต้านวัยชั้นพรีเมียม"},
]

